1: import assert from 'node:assert/strict';
2: import { before, after } from './functions.mjs';
3: 
4: async function scenario(fn, fault, concurrent = false) {
5:   const trace = { paid: false, notifications: 0, events: [], errors: [] };
6:   const db = {
7:     async transaction(callback) {
8:       let staged = false;
9:       trace.events.push('begin');
10:       try {
11:         await callback({ async markPaid() {
12:           if (fault === 'write') throw new Error('write');
13:           staged = true;
14:           trace.events.push('write');
15:         } });
16:         if (fault === 'commit') throw new Error('commit');
17:         if (staged) trace.paid = true;
18:         trace.events.push('commit');
19:       } catch (error) {
20:         trace.events.push('rollback');
21:         throw error;
22:       }
23:     },
24:   };
25:   const publish = async () => {
26:     trace.events.push('publish');
27:     if (fault === 'publish-before') throw new Error('publish-before');
28:     trace.notifications++;
29:     if (fault === 'publish-after') throw new Error('publish-after');
30:   };
31:   const invoke = () => fn(db, publish, 'invoice-7').catch((error) => trace.errors.push(error.message));
32:   if (concurrent) await Promise.all([invoke(), invoke()]);
33:   else await invoke();
34:   return trace;
35: }
36: const results = {};
37: for (const [name, fn] of Object.entries({ before, after })) {
38:   results[name] = {};
39:   for (const fault of ['none', 'write', 'commit', 'publish-before', 'publish-after']) {
40:     results[name][fault] = await scenario(fn, fault);
41:   }
42:   results[name].concurrent = await scenario(fn, 'none', true);
43: }
44: assert.equal(results.before.commit.notifications, 1, 'a notification can escape before a failed commit');
45: assert.equal(results.after.commit.notifications, 0, 'a failed commit must prevent publish in the changed function');
46: assert.equal(results.before['publish-before'].paid, false);
47: assert.equal(results.after['publish-before'].paid, true, 'publication failure cannot undo an already committed payment');
48: assert.equal(results.after['publish-before'].notifications, 0);
49: assert.equal(results.after['publish-after'].paid, true);
50: assert.equal(results.after['publish-after'].notifications, 1);
51: assert.equal(results.before['publish-after'].paid, false);
52: assert.equal(results.before['publish-after'].notifications, 1);
53: assert.deepEqual(results.after.none.events, ['begin', 'write', 'commit', 'publish']);
54: for (const result of Object.values(results)) {
55:   assert.equal(result.write.notifications, 0);
56:   assert.equal(result.write.paid, false);
57:   assert.equal(result.commit.paid, false);
58:   assert.equal(result.concurrent.notifications, 2, 'idempotent payment writes do not deduplicate external publication');
59: }
60: console.log(JSON.stringify({ assumptions: 'In-memory staged transaction and external notification counter; no actual database or process-kill simulation.', results }, null, 2));

